// Run the scenario matrix and write every results table the manuscript uses. Nothing in
// results/tables is typed by hand: each file is regenerated by `npm run export`.
import { mkdirSync, writeFileSync } from "node:fs";
import { resolveEnv, type EnvKey } from "../app/src/model/environment";
import { clusterOf, DECODER, nesFor } from "../app/src/model/identity";
import { defaultParams, p, type Params } from "../app/src/model/params";
import { ATMOSPHERES, PRESET_BY_ID, RADIATION } from "../app/src/model/presets";
import { SeedTwin, type Sample } from "../app/src/model/simulate";
import { runPopulation } from "../app/src/model/population";

const OUT = "results/tables";
mkdirSync(OUT, { recursive: true });
const P0 = defaultParams();

interface Scenario {
  id: string;
  preset: string;
  over?: Partial<Record<EnvKey, number>>;
  params?: Record<string, number>;
  group: string;
  note: string;
}

const atm = (id: string) => {
  const a = ATMOSPHERES.find((x) => x.id === id)!;
  return { p_total_kpa: a.p_total_kpa, o2_frac: a.o2_frac };
};
const rad = (id: string) => {
  const r = RADIATION.find((x) => x.id === id)!;
  return { dose_mgy_d: r.dose_mgy_d, spe_dose_mgy: r.spe_dose_mgy, ...(r.spe_start_h !== undefined ? { spe_start_h: r.spe_start_h, spe_dur_h: r.spe_dur_h } : {}) };
};

const SCENARIOS: Scenario[] = [
  { id: "ground_light", preset: "ground_petri", group: "reference", note: "1 g, 16 h light, taped dish" },
  { id: "ground_dark", preset: "ground_petri", over: { light_umol: 0, light_h_per_cycle: 0 }, group: "reference", note: "1 g, dark" },
  { id: "bric_pdfu", preset: "bric_pdfu", group: "hardware", note: "sealed, dark, 0 g" },
  { id: "bric_pdfu_1g", preset: "bric_pdfu", over: { gravity_g: 1 }, group: "hardware", note: "BRIC-PDFU ground control (1 g)" },
  { id: "bric_led", preset: "bric_led", group: "hardware", note: "sealed, 4/2 h LED, 0 g" },
  { id: "cara", preset: "cara", group: "hardware", note: "taped square dish, 0 g" },
  { id: "aph", preset: "aph", group: "hardware", note: "forced air, scrubbed, 0 g" },
  { id: "emcs_0g", preset: "emcs", over: { gravity_g: 0 }, group: "gravity", note: "EMCS static rotor" },
  { id: "emcs_0.166g", preset: "emcs", over: { gravity_g: 0.166 }, group: "gravity", note: "EMCS lunar g" },
  { id: "emcs_0.38g", preset: "emcs", over: { gravity_g: 0.38 }, group: "gravity", note: "EMCS Mars g" },
  { id: "emcs_1g", preset: "emcs", over: { gravity_g: 1 }, group: "gravity", note: "EMCS 1 g rotor" },
  { id: "leaf_gbc1", preset: "leaf_gbc1", group: "hardware", note: "LEAF GBC1, lunar g, pumped" },
  { id: "ground_exploration", preset: "ground_petri", over: atm("NASA_Exploration_56.5kPa_34pctO2"), group: "atmosphere", note: "56.5 kPa, 34 % O2" },
  { id: "ground_staged", preset: "ground_petri", over: atm("NASA_Staged_PreEVA_70.3kPa_26.5pctO2"), group: "atmosphere", note: "70.3 kPa, 26.5 % O2" },
  { id: "ground_counterfactual", preset: "ground_petri", over: atm("Counterfactual_56.5kPa_UncompensatedAir_21pctO2"), group: "atmosphere", note: "56.5 kPa air (hypoxic)" },
  { id: "bric_exploration", preset: "bric_pdfu", over: atm("NASA_Exploration_56.5kPa_34pctO2"), group: "atmosphere", note: "sealed BRIC filled with exploration atmosphere" },
  { id: "ground_hypoxia_10pct", preset: "ground_petri", over: { o2_frac: 0.1 }, group: "atmosphere", note: "10 % O2 at 1 atm" },
  { id: "ground_hypoxia_5pct", preset: "ground_petri", over: { o2_frac: 0.05 }, group: "atmosphere", note: "5 % O2 at 1 atm" },
  { id: "deep_space_spe", preset: "ground_petri", over: rad("deep_space_spe"), group: "radiation", note: "cruise + SPE, no couplings (default)" },
  {
    id: "deep_space_spe_hyp",
    preset: "ground_petri",
    over: rad("deep_space_spe"),
    params: { ros_to_aba: 1, ros_to_acc: 1, ros_to_division_arrest: 1 },
    group: "radiation",
    note: "cruise + SPE with all hypothesis couplings = 1 (illustrative only)",
  },
  { id: "ethylene_10ppm_dark", preset: "ground_petri", over: { light_umol: 0, light_h_per_cycle: 0, vent_ach: 10, eth_inlet_ppm: 10 }, group: "ethylene", note: "gassed with 10 ppm, dark" },
  { id: "mir_cabin_ethylene", preset: "cara", over: { eth_inlet_ppm: 1.4 }, group: "ethylene", note: "tape-leak exchange with cabin air at the Mir-measured 1.1-1.7 ppm (midpoint)" },
];

function summary(s: SeedTwin, sc: Scenario) {
  const last = s.samples[s.samples.length - 1];
  const minOf = (k: keyof Sample) => Math.min(...s.samples.filter((r) => r.t > 0.5).map((r) => r[k] as number));
  const maxOf = (k: keyof Sample) => Math.max(...s.samples.map((r) => r[k] as number));
  return {
    scenario: sc.id,
    group: sc.group,
    preset: sc.preset,
    note: sc.note,
    gravity_g: s.env.gravity_g,
    p_total_kpa: s.env.p_total_kpa,
    po2_kpa: +(s.env.o2_frac * s.env.p_total_kpa).toFixed(3),
    testa_rupture_h: s.milestones.testaRupture,
    endosperm_rupture_h: s.milestones.endospermRupture,
    cot_emerged_h: s.milestones.cotEmerged,
    cot_open_h: s.milestones.cotOpen,
    min_o2_surface_kpa: minOf("o2_surface_kpa"),
    min_o2_core_kpa: minOf("o2_core_min_kpa"),
    peak_eth_headspace_ppb: maxOf("eth_hs_ppb"),
    peak_eth_internal_ppb: maxOf("eth_int_ppb"),
    root_len_120h_um: last.root_len_um,
    hyp_len_120h_um: last.hyp_len_um,
    max_hook_deg: maxOf("hook_deg"),
    root_angle_120h_deg: last.root_angle_deg,
    reserve_120h: last.reserve,
    dose_120h_mgy: last.dose_mgy,
    sherwood: last.sherwood,
  };
}

function csv(rows: Record<string, unknown>[]): string {
  const cols = Object.keys(rows[0]);
  const esc = (v: unknown) => (v === null || v === undefined ? "" : typeof v === "string" && /[",\n]/.test(v) ? `"${v.replace(/"/g, '""')}"` : String(v));
  return [cols.join(","), ...rows.map((r) => cols.map((c) => esc(r[c])).join(","))].join("\n") + "\n";
}

const sums: Record<string, unknown>[] = [];
const sims = new Map<string, SeedTwin>();
for (const sc of SCENARIOS) {
  const params: Params = { ...P0, ...(sc.params ?? {}) };
  const s = new SeedTwin(params, resolveEnv(PRESET_BY_ID.get(sc.preset)!, sc.over ?? {}));
  s.runTo(120);
  sims.set(sc.id, s);
  sums.push(summary(s, sc));
  writeFileSync(`${OUT}/timeseries_${sc.id}.csv`, csv(s.samples as unknown as Record<string, unknown>[]));
  console.log(`${sc.id}: ER ${s.milestones.endospermRupture?.toFixed(1)} h`);
}
writeFileSync(`${OUT}/scenario_summary.csv`, csv(sums));

// ---- Bassel per-cell expansion profile (reference run)
{
  const s = sims.get("ground_light")!;
  const ref = s.profiles.get(3)!;
  const rows: Record<string, unknown>[] = [];
  for (const [t, prof] of s.profiles) for (const x of prof) rows.push({ hours: t, cortical_index: x.index, volume_um3: x.volume, rel_to_3h: x.volume / ref.find((q) => q.index === x.index)!.volume });
  writeFileSync(`${OUT}/cortex_expansion_profile.csv`, csv(rows));
}

// ---- out-of-sample check: hydrotime (substrate water potential), not used in calibration
{
  const thetaH = 34.352; // MPa h, Footitt 2019 Table 1 (15 °C)
  const psiB = p(P0, "psi_base_mpa");
  const rows: Record<string, unknown>[] = [];
  for (const psi of [0, -0.1, -0.25, -0.4, -0.55, -0.7, -0.85]) {
    const s = new SeedTwin(P0, resolveEnv(PRESET_BY_ID.get("ground_petri")!, { substrate_psi_mpa: psi }), { germinationOnly: true });
    s.runTo(200);
    rows.push({
      psi_mpa: psi,
      model_endosperm_rupture_h: s.milestones.endospermRupture,
      hydrotime_t50_h: thetaH / (psi - psiB),
      model_rate_per_h: s.milestones.endospermRupture ? 1 / s.milestones.endospermRupture : 0,
      hydrotime_rate_per_h: (psi - psiB) / thetaH,
    });
  }
  writeFileSync(`${OUT}/hydrotime_check.csv`, csv(rows));
}

// ---- simulated exposure vs observed decoder signature, per atlas cluster
{
  const rows: Record<string, unknown>[] = [];
  for (const id of ["bric_pdfu", "ground_light", "ground_counterfactual"]) {
    const s = new SeedTwin(P0, resolveEnv(PRESET_BY_ID.get(SCENARIOS.find((x) => x.id === id)!.preset)!, SCENARIOS.find((x) => x.id === id)!.over ?? {}));
    s.runTo(24); // germinating-embryo atlas time point
    const acc = new Map<string, { o2: number; n: number }>();
    for (let i = 0; i < s.cells.n; i++) {
      const cl = clusterOf(s.template, i, 24);
      if (!cl || !s.active[i]) continue;
      const a = acc.get(cl) ?? { o2: 0, n: 0 };
      a.o2 += s.o2[i] / 1000;
      a.n++;
      acc.set(cl, a);
    }
    for (const [cl, a] of acc)
      rows.push({
        scenario: id,
        cluster: cl,
        cell_type: DECODER.clusters[cl].cell_type,
        n_cells: a.n,
        mean_o2_kpa_24h: a.o2 / a.n,
        o2_deficit_kpa: s.env.o2_frac * s.env.p_total_kpa - a.o2 / a.n,
        observed_low_oxygen_nes: nesFor("low_oxygen", cl),
        observed_hypobaria_nes: nesFor("hypobaria", cl),
      });
  }
  writeFileSync(`${OUT}/exposure_vs_decoder.csv`, csv(rows));
}

// ---- seed populations (between-seed ψb spread from Footitt 2019)
{
  const pops: [string, string, Partial<Record<EnvKey, number>>][] = [
    ["ground", "ground_petri", {}],
    ["BRIC-PDFU 0 g", "bric_pdfu", {}],
    ["56.5 kPa air (hypoxic)", "ground_petri", atm("Counterfactual_56.5kPa_UncompensatedAir_21pctO2")],
    ["water stress -0.4 MPa", "ground_petri", { substrate_psi_mpa: -0.4 }],
  ];
  const curves: Record<string, unknown>[] = [];
  const summaryRows: Record<string, unknown>[] = [];
  for (const [label, preset, over] of pops) {
    const r = runPopulation(P0, resolveEnv(PRESET_BY_ID.get(preset)!, over), 60, 20261106, 96);
    r.times.forEach((tt, i) => curves.push({ scenario: label, seed: i, psi_b_offset_mpa: r.offsets[i], endosperm_rupture_h: tt }));
    summaryRows.push({ scenario: label, n: r.times.length, gmax: r.gmax, t50_h: r.t50, u8416_h: r.u8416, u7525_h: r.u7525 });
    console.log(`population ${label}: t50 ${r.t50?.toFixed(1)} h, u84-16 ${r.u8416?.toFixed(1)} h`);
  }
  writeFileSync(`${OUT}/population_curves.csv`, csv(curves));
  writeFileSync(`${OUT}/population_summary.csv`, csv(summaryRows));
}

// ---- ledger tier census
{
  const rows = Object.entries(
    (await import("../app/src/model/params")).LEDGER.reduce<Record<string, number>>((acc, e) => ((acc[e.tier] = (acc[e.tier] ?? 0) + 1), acc), {}),
  ).map(([tier, n]) => ({ tier, n }));
  writeFileSync(`${OUT}/ledger_tiers.csv`, csv(rows));
}
console.log(`wrote ${OUT}`);
